{
  "query": "multifocal motor neuropathy ALS misdiagnosis diagnostic criteria",
  "results": [
    {
      "title": "Multifocal motor neuropathy vs motor neuron disease: diagnostic pitfalls",
      "finding": "Multifocal motor neuropathy is purely LMN; UMN signs (Babinski, Hoffmann, brisk reflexes) do not occur in MMN. Development of UMN signs in presumed MMN should prompt immediate reassessment for a motor neuron disease."
    },
    {
      "title": "Anti-GM1 antibodies: specificity thresholds",
      "finding": "Anti-GM1 IgM titer >1:400 has high specificity for MMN (>90%). Titers <1:200 have poor specificity and can be found in ALS, other neuropathies. Low-titer positivity should not anchor MMN diagnosis."
    },
    {
      "title": "IVIG non-response in MMN",
      "finding": "True MMN consistently responds to IVIG within 3-6 months. Failure of sustained response should prompt diagnosis reconsideration."
    }
  ],
  "summary": "UMN signs in presumed multifocal motor neuropathy mandate immediate reconsideration of the diagnosis, including a motor neuron disorder. Low anti-GM1 titers are non-specific. Sustained IVIG non-response should trigger diagnostic reassessment."
}

