{
  "test_type": "Formal FND sign assessment",
  "findings": [
    {
      "finding": "ARM DRIFT TEST: Left arm placed at 90 degrees horizontal. Over 10 seconds: LEFT ARM DRIFTS UPWARD (toward ceiling) rather than downward. Organic UMN weakness causes arm drift DOWN with pronation due to gravity and loss of UMN antigravity support. Arm drifting UPWARD is physiologically impossible with organic weakness \u2014 there is no muscle that could produce upward drift with hemiparesis, and it requires active motor effort to push upward."
    },
    {
      "finding": "POSITIVE Hoover sign: Left hip extension 5/5 with right leg contralateral flexion resistance."
    },
    {
      "finding": "Strength with distraction: Left arm strength improves from 2/5 to 4/5 when asked to count backwards from 100."
    }
  ],
  "quantitative_data": {
    "diagnosis": "Multiple positive non-organic examination signs"
  },
  "impression": "Upward arm drift observed in the affected limb during the arm-drop test, a pattern inconsistent with the biomechanics of organic upper motor neuron weakness. Give-way weakness pattern and strength improvement with attentional distraction also documented",
  "recommended_actions": [
    "Positive non-organic examination signs documented. Correlate clinically."
  ]
}

