{
  "proposed": "IV alteplase (tPA) 0.9 mg/kg for acute ischemic stroke",
  "interactions": [
    "Ibuprofen (intermittent NSAID): antiplatelet effect is not a contraindication to alteplase but modestly raises bleeding risk; avoid further NSAID dosing peri-thrombolysis.",
    "Sumatriptan: no clinically significant interaction with alteplase; serotonergic agent unrelated to thrombolysis bleeding risk."
  ],
  "contraindications": [
    "Cervical (vertebral) artery dissection is not by itself a contraindication to IV alteplase for the resulting ischemic stroke when within the time window and other criteria are met (AHA/ASA 2019, Class IIa)."
  ],
  "warnings": [
    "Confirm INR <1.7, platelets >=100,000, and normal glucose before thrombolysis.",
    "Intracranial extension of the dissection must be excluded before thrombolysis given subarachnoid-hemorrhage risk; vessel imaging in this case shows the dissection confined to the extracranial V3 segment."
  ],
  "formulary_status": "IV alteplase is on formulary for acute ischemic stroke",
  "alternatives": [
    "If outside the thrombolysis window or contraindicated: antithrombotic therapy for the dissection - either antiplatelet or anticoagulation, which were shown equivalent in CADISS.",
    "Mechanical thrombectomy if a large-vessel occlusion is present (not the case here - distal PICA-territory infarct)."
  ],
  "summary": ""
}

