{
  "query": "basilar artery occlusion thrombectomy outcomes treatment guidelines",
  "results": [
    {
      "title": "Endovascular Therapy for Acute Basilar-Artery Occlusion (ATTENTION Trial)",
      "authors": "Tao C, Nogueira RG, et al.",
      "journal": "NEJM",
      "year": "2023",
      "key_finding": "Endovascular thrombectomy within 12 hours of estimated occlusion time significantly improved functional outcomes compared to medical management alone in Chinese patients with acute basilar artery occlusion (mRS 0-3 at 90 days: 46% vs 23%)."
    },
    {
      "title": "Endovascular Therapy for Basilar-Artery Occlusion (BAOCHE Trial)",
      "authors": "Langezaal LCM, et al.",
      "journal": "NEJM",
      "year": "2023",
      "key_finding": "Thrombectomy within 6-24 hours of estimated onset improved functional outcome in basilar artery occlusion patients selected by advanced imaging (mRS 0-3: 44% vs 25%)."
    },
    {
      "title": "Basilar Artery Occlusion: Clinical and Radiographic Predictors of Outcome",
      "authors": "Mattle HP, Arnold M, et al.",
      "journal": "Stroke",
      "year": "2011",
      "key_finding": "Mortality in untreated basilar artery occlusion approaches 85-95%. Early recanalization is the strongest predictor of favorable outcome."
    }
  ],
  "summary": "Basilar artery occlusion is a neurovascular emergency with extremely high mortality without treatment. The ATTENTION (2023) and BAOCHE (2023) trials demonstrated clear benefit of endovascular thrombectomy within 12-24 hours of symptom onset, with improved rates of functional independence compared to medical therapy alone. Patient selection using advanced imaging (CTA, CT perfusion, or MRI) is critical. IV thrombolysis may be used as a bridge to thrombectomy. Fluctuating or stuttering symptoms are recognized presentations of basilar territory ischemia."
}

