{
  "query": "Differentiating migraine white matter lesions from multiple sclerosis on MRI",
  "results": [
    {
      "title": "MRI white matter lesions in migraine versus multiple sclerosis: a systematic review",
      "source": "Neurology Reviews 2023",
      "key_finding": "Migraine-related WML are typically small (<3mm), punctate, subcortical, and lack periventricular orientation. MS lesions tend to be larger, ovoid, periventricular with perpendicular orientation (Dawson fingers), and may enhance with gadolinium."
    },
    {
      "title": "Diagnostic challenges in radiologically isolated syndrome and early MS",
      "source": "Lancet Neurology 2024",
      "key_finding": "Up to 10% of MS patients are OCB-negative at initial presentation. Serial MRI showing dissemination in time is critical when CSF is non-contributory. Periventricular lesion morphology (perpendicular to ventricle) has high specificity for MS even when few lesions are present."
    },
    {
      "title": "McDonald 2017 criteria: practical application and common pitfalls",
      "source": "Multiple Sclerosis Journal 2022",
      "key_finding": "A single periventricular lesion with Dawson finger morphology should raise suspicion for MS even if other criteria are not initially met. Follow-up imaging at 3-6 months is recommended when initial findings are inconclusive."
    }
  ],
  "summary": "Migraine-related white matter lesions are common but typically differ from MS lesions in size, morphology, and distribution. Periventricular lesions perpendicular to the ventricle (Dawson fingers) are more specific for MS. OCB-negative MS occurs in 5-10% of cases. When initial findings are equivocal, serial MRI demonstrating dissemination in time is a key diagnostic strategy per McDonald 2017 criteria."
}

