{
  "query": "Hashimoto encephalopathy vs anti-NMDAR encephalitis differential diagnosis",
  "results": [
    {
      "title": "Steroid-responsive encephalopathy associated with autoimmune thyroiditis (SREAT): a diagnostic pitfall",
      "authors": "Laurent C, et al.",
      "journal": "J Neurol Neurosurg Psychiatry",
      "year": "2016",
      "key_finding": "SREAT (Hashimoto encephalopathy) is a diagnosis of exclusion. Anti-TPO antibodies are present in 10-15% of the healthy population and do not prove causation. True SREAT should be differentiated from anti-NMDAR encephalitis by testing for neuronal surface antibodies."
    },
    {
      "title": "Anti-NMDA receptor encephalitis: clinical analysis of a series and review",
      "authors": "Dalmau J, et al.",
      "journal": "Lancet Neurol",
      "year": "2019",
      "key_finding": "Anti-NMDAR encephalitis is the most common autoimmune encephalitis. Characteristic progression: psychiatric symptoms, seizures, movement disorders, autonomic instability, decreased consciousness. CSF anti-NMDAR antibodies are 100% sensitive vs 85.6% for serum."
    }
  ],
  "summary": "Hashimoto encephalopathy (SREAT) and antibody-mediated autoimmune encephalitis can present similarly in patients with elevated anti-thyroid antibodies. SREAT is a diagnosis of exclusion; anti-TPO positivity is common and nonspecific. Current evidence supports comprehensive neuronal antibody evaluation before attributing encephalopathy to SREAT alone."
}

